package com.example.spring_blog.user;import com.example.spring_blog.error.Exception400;import com.example.spring_blog.error.Exception500;import com.example.spring_blog.util.Define;import com.example.spring_blog.util.MailUtil;import jakarta.mail.internet.MimeMessage;import jakarta.servlet.http.HttpSession;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.mail.javamail.JavaMailSender;import org.springframework.mail.javamail.MimeMessageHelper;import org.springframework.stereotype.Service;import java.io.Serializable;import java.time.LocalDateTime;// 메일 발송, 인증번호 확인@Slf4j@RequiredArgsConstructor@Servicepublic class MailService {    //    의존성 설정, application.yaml의 spring.mail 설정으로 스프링 부트가 만들어준 빈(Bean) 객체이다.    private final JavaMailSender javaMailSender;    //    record 문법 : JDK 16부터 정식으로 사용 가능한 문법//    이 아래 한 줄이 클래스를 설계함. 필드 + GETTER, Equals, HashCode, toString을 가진 녀석을 자바가 대신 만들어준다.//    대신 Setter는 없다.    private record EmailCode(String code, LocalDateTime expiresAt) implements Serializable {        boolean isExpired() {            return LocalDateTime.now().isAfter(expiresAt);        }    }    //    1. 인증번호 발송    public void sendVerificationCode(String email, HttpSession session) {//        1-1. 6자리 인증번호 생성        String code = MailUtil.generateCode();//        1-2. 메일 작성 : HTML 본문, 첨부 파일 등을 담을 수 있는 메일 형식        MimeMessage mimeMessage = javaMailSender.createMimeMessage();        try {            MimeMessageHelper helper = new MimeMessageHelper(mimeMessage, false, "UTF-8");            helper.setTo(email); // 받는 사람 이메일 주소            helper.setSubject("[스프링 블로그] 회원가입 인증번호"); // 제목            helper.setText(                    "<h3>인증번호는 " + code + "입니다.</h3>" +                            "<p>인증번호는 " + Define.CODE_EXPIRE_IN_MINUTES + "분 후에 만료됩니다.</p>",                    true            );//        1-3 방송 (실패하면....)            javaMailSender.send(mimeMessage);        } catch (Exception e) {            throw new Exception500("메일 작성중 오류가 발생했습니다.");        }        session.setAttribute(Define.EMAIL_CODE_PREFIX + email,                new EmailCode(code, LocalDateTime.now().plusMinutes(Define.CODE_EXPIRE_IN_MINUTES)));        log.info("인증 번호 발송 완료 - 이메일 : {}", email);    }    public boolean verifyCode(String email, String code, HttpSession session) {        String key = Define.EMAIL_CODE_PREFIX + email;        EmailCode savedEmailCode = (EmailCode) session.getAttribute(key);        if (savedEmailCode == null) {            throw new Exception400("인증 번호를 먼저 요청해주세요.");        }        if (savedEmailCode.isExpired()) {            throw new Exception400("인증번호가 만료되었습니다.");        }        if (!savedEmailCode.code().equals(code)) {            throw new Exception400("인증번호가 일치하지 않습니다.");        }//        사용된 인증번호는 삭제.        session.removeAttribute(key);//        인증 완료된 이메일을 세션에 기록        session.setAttribute(Define.VERIFIED_EMAIL, email);        return true;    }}